mapper.update:
update tb_player_package
set  update_by = #{accountId},
     update_time = now(),
     num = num - #{number}
where id = #{id}

mapper.select:
select tb.id, tb.num, tb.obj_id, props_name, props_intro, gp.drop_probability, grade, gp.type as props_type, selling_price, can_use, allow_open, pdd.id as pdd_id, pdd.props_id as props_id, pdd.obj_id as pdd_obj_id, pdd.type as pdd_type, pdd.num as pdd_num, pdd.drop_probability as pdd_drop_probability from tb_player_package tb left join tb_game_props gp on gp.id = tb.obj_id left join tb_props_drop_detail pdd on pdd.props_id = gp.id
tb.del_flag = false and tb.player_id = #{playerId}
and tb.id = #{id}
and gp.type in #{type}
